(breakbeforebraces)=

**BreakBeforeBraces** (`BraceBreakingStyle`) {versionbadge}`clang-format 3.7` {ref}`¶ <BreakBeforeBraces>`

: The brace breaking style to use.

  Possible values:

  - `BS_Attach` (in configuration: `Attach`)
    Always attach braces to surrounding context.

    ```c++
    namespace N {
    enum E {
      E1,
      E2,
    };

    class C {
    public:
      C();
    };

    bool baz(int i) {
      try {
        do {
          switch (i) {
          case 1: {
            foobar();
            break;
          }
          default: {
            break;
          }
          }
        } while (--i);
        return true;
      } catch (...) {
        handleError();
        return false;
      }
    }

    void foo(bool b) {
      if (b) {
        baz(2);
      } else {
        baz(5);
      }
    }

    void bar() { foo(true); }
    } // namespace N
    ```

  - `BS_Linux` (in configuration: `Linux`)
    Like `Attach`, but break before braces on function, namespace and
    class definitions.

    ```c++
    namespace N
    {
    enum E {
      E1,
      E2,
    };

    class C
    {
    public:
      C();
    };

    bool baz(int i)
    {
      try {
        do {
          switch (i) {
          case 1: {
            foobar();
            break;
          }
          default: {
            break;
          }
          }
        } while (--i);
        return true;
      } catch (...) {
        handleError();
        return false;
      }
    }

    void foo(bool b)
    {
      if (b) {
        baz(2);
      } else {
        baz(5);
      }
    }

    void bar() { foo(true); }
    } // namespace N
    ```

  - `BS_Mozilla` (in configuration: `Mozilla`)
    Like `Attach`, but break before braces on enum, function, and record
    definitions.

    ```c++
    namespace N {
    enum E
    {
      E1,
      E2,
    };

    class C
    {
    public:
      C();
    };

    bool baz(int i)
    {
      try {
        do {
          switch (i) {
          case 1: {
            foobar();
            break;
          }
          default: {
            break;
          }
          }
        } while (--i);
        return true;
      } catch (...) {
        handleError();
        return false;
      }
    }

    void foo(bool b)
    {
      if (b) {
        baz(2);
      } else {
        baz(5);
      }
    }

    void bar() { foo(true); }
    } // namespace N
    ```

  - `BS_Stroustrup` (in configuration: `Stroustrup`)
    Like `Attach`, but break before function definitions, `catch`, and
    `else`.

    ```c++
    namespace N {
    enum E {
      E1,
      E2,
    };

    class C {
    public:
      C();
    };

    bool baz(int i)
    {
      try {
