          switch (i) {
          case 1: {
            foobar();
            break;
          }
          default: {
            break;
          }
          }
        } while (--i);
        return true;
      }
      catch (...) {
        handleError();
        return false;
      }
    }

    void foo(bool b)
    {
      if (b) {
        baz(2);
      }
      else {
        baz(5);
      }
    }

    void bar() { foo(true); }
    } // namespace N
    ```

  - `BS_Allman` (in configuration: `Allman`)
    Always break before braces.

    ```c++
    namespace N
    {
    enum E
    {
      E1,
      E2,
    };

    class C
    {
    public:
      C();
    };

    bool baz(int i)
    {
      try
      {
        do
        {
          switch (i)
          {
          case 1:
          {
            foobar();
            break;
          }
          default:
          {
            break;
          }
          }
        } while (--i);
        return true;
      }
      catch (...)
      {
        handleError();
        return false;
      }
    }

    void foo(bool b)
    {
      if (b)
      {
        baz(2);
      }
      else
      {
        baz(5);
      }
    }

    void bar() { foo(true); }
    } // namespace N
    ```

  - `BS_Whitesmiths` (in configuration: `Whitesmiths`)
    Like `Allman` but always indent braces and line up code with braces.

    ```c++
    namespace N
      {
    enum E
      {
      E1,
      E2,
      };

    class C
      {
    public:
      C();
      };

    bool baz(int i)
      {
